//go:build skopos_upstream

// This file is copied into the pinned Loki tree by scripts/compat/loki-upstream.sh. The build tag
// keeps it out of the Skopos module, where defaultGeneratorConfig does not
// exist.
package bench

import (
	"encoding/json"
	"os"
	"testing"
)

// TestSkoposDumpCorpus writes the query corpus generated by the pinned Loki
// benchmark package. The Skopos harness injects this file into the extracted
// Loki tree, so the corpus always comes from the pinned upstream source instead
// of a hand-copied list.
//
// It lives in package bench to read the unexported defaultGeneratorConfig.
func TestSkoposDumpCorpus(t *testing.T) {
	out := os.Getenv("SKOPOS_UPSTREAM_CORPUS_OUT")
	if out == "" {
		t.Fatal("SKOPOS_UPSTREAM_CORPUS_OUT is required")
	}

	payload := map[string]any{
		"provenance": map[string]string{
			"project":        "github.com/grafana/loki",
			"version":        os.Getenv("SKOPOS_LOKI_VERSION"),
			"commit":         os.Getenv("SKOPOS_LOKI_COMMIT"),
			"archive_sha256": os.Getenv("SKOPOS_LOKI_ARCHIVE_SHA256"),
			"generator":      "pkg/logql/bench.(*GeneratorConfig).GenerateTestCases",
			"seed":           "1",
		},
		"cases": defaultGeneratorConfig.GenerateTestCases(),
	}

	data, err := json.MarshalIndent(payload, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	data = append(data, '\n')
	if err := os.WriteFile(out, data, 0o644); err != nil {
		t.Fatal(err)
	}
	t.Logf("wrote %d cases to %s", len(payload["cases"].([]TestCase)), out)
}
